window.SUBJECTS.push({"id":"env","n":"Environment","tab":"Environment","w":"Ecology, protected areas and biodiversity, pollution and climate.","topics":[{"id":"ecology","n":"Ecology and Sustainability","qs":[{"id":"q0088","q":"Which environmental concept best describes the responsible and ethical use of resources to meet the needs of the present without compromising the ability of future generations to meet their own needs?","o":["Exploitation","Conservation","Overconsumption","Preservation"],"a":1,"x":"Using resources wisely so future generations can also meet their needs is conservation, which is the idea behind sustainable development.","e":"The definition comes from the Brundtland Commission's report 'Our Common Future' (1987).","src":["ASO 18 Aug 2025 S3"]},{"id":"q0249","q":"Which environmental issue, among the following, poses a significant challenge to infrastructure development?","o":["Increase in online commerce","Decline in rural populations","Rapid urbanisation","Unsustainable use of resources"],"a":3,"x":"Unsustainable use of resources — overdrawing groundwater, sand mining, clearing forests — makes infrastructure costlier and less durable.","e":"Sustainable infrastructure uses resources at a rate nature can replenish.","src":["ASO 20 Aug 2025 S2"]},{"id":"q1794","q":"Which of the following comprise the natural environment? I. Land II. Water III. Plants IV. Animals","o":["I and II","II, III and IV","III and IV","I, II, III and IV"],"a":3,"x":"The natural environment includes land, water, air, plants and animals: everything not made by humans.","e":"The human-made environment: buildings, roads, bridges.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q0947","q":"In the context of sustainable development, which principle ensures equal opportunities for all?","o":["Empowerment","Productivity","Equity","Sustainability"],"a":2,"x":"Equity in sustainable development means fair and equal access to resources and opportunities for everyone, now and in future generations.","e":"The three pillars of sustainability: economic, social and environmental.","src":["PRT 18 Feb 2026 S2"]},{"id":"q1167","q":"What is a defining characteristic of a stratified ecosystem?","o":["Horizontal layering of vegetation","Vertical layering of environmental conditions and communities of organisms","Uniform distribution of organisms throughout the ecosystem","Random distribution of nutrients and resources within the ecosystem"],"a":1,"x":"Stratification is the vertical layering of an ecosystem: in a forest, trees, shrubs, herbs and ground layer each have different light and conditions.","e":"Tropical rainforests show the most layers.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1244","q":"In which process do microorganisms break down organic matter into simple compounds, releasing nutrients back into the ecosystem?","o":["Photosynthesis","Respiration","Decomposition","Transpiration"],"a":2,"x":"Decomposition is the breakdown of dead organic matter by bacteria and fungi into simple compounds, returning nutrients to the ecosystem.","e":"Decomposers close the nutrient cycle.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1273","q":"In a food chain, small carnivores or secondary consumers are present in which tropical level?","o":["Trophic level fourth","Trophic level first","Trophic level second","Trophic level third"],"a":3,"x":"In a food chain, producers are the 1st trophic level, herbivores (primary consumers) the 2nd, and small carnivores (secondary consumers) the 3rd.","e":"Grass → grasshopper → frog → snake: the frog is at the 3rd level.","src":["PRT 10 Apr 2026 S1"]},{"id":"q0767","q":"Which ecological concept did Charles Elton introduce in 1927?","o":["Biogeochemical cycle","Dominance hierarchies","Evolutionary ecology","Pyramid of numbers"],"a":3,"x":"Charles Elton introduced the pyramid of numbers (Eltonian pyramid) in 1927, showing how the number of organisms usually falls at each higher trophic level.","e":"A tree ecosystem gives an inverted pyramid of numbers: one tree, many insects.","src":["PGT 25 Sep 2025"]}]},{"id":"biodiversity","n":"Parks, Forests and Biodiversity","qs":[{"id":"q0272","q":"Which of the following Indian states has the lowest percentage of its geographical area under the forest, according to the India State of Forest Report 2021?","o":["Gujarat","Haryana","Rajasthan","Uttar Pradesh"],"a":1,"x":"India State of Forest Report 2021: Haryana had the lowest share of area under forest (about 3.6%).","e":"Highest share: Mizoram (about 84.5%). Largest forest area: Madhya Pradesh.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0341","q":"'Red Sanders' is an endangered tree species found in which of the following states?","o":["West Bengal","Maharashtra","Andhra Pradesh","Rajasthan"],"a":2,"x":"Red Sanders (Pterocarpus santalinus) is endemic to the southern Eastern Ghats of Andhra Pradesh, mainly the Seshachalam hills, and is heavily smuggled for its red wood.","e":"It is listed as Endangered on the IUCN Red List.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0352","q":"Kashmir stag, Spotted deer and Tibetan antelope are found in which of the following forests?","o":["Montane forests","Tropical thorn forests","Mangrove forests","Thorn forests"],"a":0,"x":"Montane (mountain) forests of the Himalaya shelter the Kashmir stag (hangul), spotted deer, Tibetan antelope, wild sheep and yak.","e":"Thorn forests have camels, wild asses and foxes; mangroves have the Royal Bengal tiger and crocodiles.","src":["ASO 21 Aug 2025 S2"]},{"id":"q1608","q":"Which one is not related to the protection of flora and fauna?","o":["Wildlife Sanctuary","National Park","Biosphere Reserve","Amusement Park"],"a":3,"x":"Wildlife sanctuaries, national parks and biosphere reserves protect flora and fauna. An amusement park is for entertainment.","e":"India's first national park: Hailey (now Jim Corbett), 1936.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0492","q":"In which of the following states is the Jaldapara National Park located?","o":["Tamil Nadu","Kerala","West Bengal","Madhya Pradesh"],"a":2,"x":"Jaldapara National Park is in Alipurduar district of north Bengal, known for the one-horned rhinoceros.","e":"Nearby, Gorumara National Park also has rhinos.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0613","q":"Which among the following national parks is the only national park in which four Big Cats – tiger, leopard, snow leopard and clouded leopard are found?","o":["Narayan National Park","Namdapha National Park","Kaziranga National Park","Dachigam National Park"],"a":1,"x":"Namdapha National Park in Arunachal Pradesh is the only park in India where four big cats — tiger, leopard, snow leopard and clouded leopard — are found.","e":"It is also home to the hoolock gibbon, India's only ape.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0653","q":"In which of the following states is the Marine National Park located?","o":["Madhya Pradesh","Maharashtra","Tamil Nadu","Gujarat"],"a":3,"x":"The Marine National Park in the Gulf of Kutch, Jamnagar, Gujarat, was India's first marine national park (1982), known for coral reefs.","e":"Mahatma Gandhi Marine National Park is at Wandoor in the Andaman Islands.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0692","q":"Which among the following national parks is located in Manipur?","o":["Coringa Wildlife Sanctuary","Keibul Lamjao National Park","Jim Corbett National Park","Nagarhole National Park"],"a":1,"x":"Keibul Lamjao National Park in Manipur is the world's only floating national park, on the phumdis of Loktak Lake, and the home of the sangai (brow-antlered deer).","e":"Nagarhole is in Karnataka; Jim Corbett in Uttarakhand; Coringa is a sanctuary in Andhra Pradesh.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q2036","q":"Which of the following tree(s) is/are found in tropical evergreen forests? I. Ebony II. Mahogany III. Rosewood","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Tropical evergreen (rain) forests have hardwood trees such as ebony, mahogany and rosewood.","e":"Tropical deciduous forests: teak, sal, sandalwood.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2078","q":"Which of the following trees are found in Tropical rain forest? I. Mahogany II. Ebony III. Rosewood","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Tropical rain (evergreen) forests have mahogany, ebony and rosewood trees.","e":"Evergreen forests: Western Ghats, North-East, Andaman.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2157","q":"Which of the following type of forests are the most widespread forests in India?","o":["Tropical Thorn forests","Tropical Deciduous forests","Montane forests","Littoral and Swamp Forest"],"a":1,"x":"Tropical deciduous (monsoon) forests are India's most widespread forests; they shed leaves in the dry season. Teak and sal are typical trees.","e":"Moist deciduous: over 100 cm rain; dry deciduous: 70–100 cm.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2460","q":"On which date is the World Wetlands Day celebrated?","o":["February 1st","February 2nd","February 3rd","February 4th"],"a":1,"x":"World Wetlands Day is observed on 2 February, marking the Ramsar Convention signed on that day in 1971.","e":"Ramsar is in Iran.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2492","q":"Which of the following type of forests are found in the western slope of the Western Ghats, hills of the northeastern region and the Andaman Nicobar Islands?","o":["Tropical Evergreen and Semi Evergreen forests","Montane forests","Tropical thorn forests","Tropical deciduous forests"],"a":0,"x":"Tropical evergreen and semi-evergreen forests grow on the western slopes of the Western Ghats, the north-eastern hills and the Andaman and Nicobar Islands, where rainfall exceeds 200 cm.","e":"Also called tropical rainforests.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2532","q":"In which of the following states is the Sultanpur National Park situated?","o":["Madhya Pradesh","Rajasthan","Maharashtra","Haryana"],"a":3,"x":"Sultanpur National Park, a bird sanctuary and Ramsar site, is in Gurugram district, Haryana.","e":"Haryana's other park: Kalesar.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2605","q":"Which of the following statement(s) regarding tropical evergreen forest is/are correct? I. They are also called tropical rainforests. II. The trees of these forests shed leaves completely twice a year.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Tropical evergreen forests are also called tropical rainforests. Their trees do not shed all their leaves at one time, so they stay green all year; statement II is wrong.","e":"Deciduous forests shed leaves in the dry season.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2673","q":"Which of the following is a biosphere reserve in India? I. Sundarbans II. Nilgiri III. Manas","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Sundarbans (West Bengal), Nilgiri (the first, 1986) and Manas (Assam) are all biosphere reserves in India.","e":"India has 18 biosphere reserves.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1295","q":"How many distinct floristic regions can India be divided into?","o":["7","8","6","5"],"a":1,"x":"India is divided into 8 floristic regions: Western Himalayas, Eastern Himalayas, Assam, Indus plain, Ganga plain, Deccan, Malabar and Andamans (after Chatterjee).","e":"The Eastern Himalayas and Western Ghats are biodiversity hotspots.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1328","q":"Which among the following national parks is not located in West Bengal?","o":["Kanha National Park","Jaldapara National Park","Gorumara National Park","Buxa Tiger Reserve"],"a":0,"x":"Kanha National Park is in Madhya Pradesh. Jaldapara, Gorumara and Buxa Tiger Reserve are in West Bengal.","e":"Kanha inspired Kipling's 'The Jungle Book' and protects the barasingha.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1283","q":"Teak is the most prominent species of which type of forest in India?","o":["Tropical deciduous forest","Tropical evergreen forest","Thorn forests and scrubs","Montane forest"],"a":0,"x":"Teak is the most important species of India's tropical deciduous (monsoon) forests, along with sal, sandalwood and bamboo.","e":"Tropical deciduous forests are India's most widespread forest type.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1378","q":"Which of the following national parks is known for the lesser panda (red panda)?","o":["Bandipur National Park","Jim Corbett National Park","Nagarhole National Park","Singalila National Park"],"a":3,"x":"Singalila National Park in Darjeeling, West Bengal, is known for the red panda (lesser panda). Bandipur and Nagarhole are in Karnataka; Jim Corbett in Uttarakhand.","e":"The red panda is Sikkim's state animal.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1538","q":"Since 1986, in which IUCN category has the Indian bison been listed because of its declining population?","o":["Near Threatened","Critically Endangered","Vulnerable","Extinct in the Wild"],"a":2,"x":"The Indian bison (gaur) has been listed as Vulnerable on the IUCN Red List since 1986 because its population is falling.","e":"The gaur is the largest wild cattle species.","src":["TGT 24 Aug 2025 S3"]},{"id":"q0785","q":"According to the Forest Survey Report, 2021, which of the following forest areas has seen an increase of 17 square kilometres compared to the previous assessment?","o":["Montane","Thorn","Tropical deciduous","Mangrove"],"a":3,"x":"The India State of Forest Report 2021 showed mangrove cover up by 17 sq km over the 2019 assessment, to 4,992 sq km.","e":"West Bengal (Sundarbans) has the largest mangrove cover, then Gujarat.","src":["PGT 11 Jul 2025 S1"]}]},{"id":"pollution","n":"Pollution","qs":[{"id":"q0733","q":"Which one of the following should not be added to convert waste to compost in a compost pit?","o":["Leaves","Microorganisms","Plastic items","Water"],"a":2,"x":"Plastic should not go into a compost pit: it is non-biodegradable. Leaves, water and microorganisms help composting.","e":"Vermicomposting uses red wiggler earthworms.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q2072","q":"Which of the following is NOT an organic impurity?","o":["Oil","Nitrates","Human farces","Animal waste"],"a":1,"x":"Nitrates are inorganic impurities. Oil, human faeces and animal waste are organic impurities in water.","e":"Organic = carbon-based matter from living things.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2668","q":"Which of the following is a by product of wastewater treatment? I. Sludge II. Biogas","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Sewage treatment produces sludge, which is broken down by bacteria to give biogas; both are by-products (NCERT Class 7).","e":"Biogas from sludge can run the plant.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1205","q":"Which of the following fuels causes the most pollution?","o":["Kerosene","CNG","Petrol","LNG"],"a":0,"x":"Among these, kerosene pollutes the most: it burns with soot, smoke and harmful gases. CNG and LNG are the cleanest fossil fuels.","e":"Delhi's buses switched to CNG in 2002 on Supreme Court orders.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1518","q":"What is the revised PM10 levels reduction target of the National Clean Air Program (NCAP) by 2025-26 as compared to the baseline year of 2017-18?","o":["Up to 50%","Up to 40%","Up to 60%","Up to 30%"],"a":1,"x":"Under the National Clean Air Programme (launched 2019), the revised target is a cut of up to 40% in PM10 levels by 2025-26 from the 2017-18 baseline, in 131 non-attainment cities.","e":"The original target was 20–30% by 2024.","src":["TGT 24 Aug 2025 S1"]}]},{"id":"climate","n":"Climate Change and Treaties","qs":[{"id":"q0123","q":"What is the primary purpose of the Kyoto Protocol, an international treaty related to environmental sustainability?","o":["To increase industrial waste production","To reduce greenhouse gas emissions","To encourage over-exploitation of natural resources","To promote deforestation"],"a":1,"x":"The Kyoto Protocol (adopted 1997, in force 2005) set binding greenhouse-gas cuts for developed countries under the UNFCCC.","e":"The Paris Agreement (2015) replaced it with pledges from all countries.","src":["ASO 19 Aug 2025 S2"]},{"id":"q2153","q":"Which of the following statements is true regarding HFCs?","o":["It contains chlorine","It is not categorised as a greenhouse gas","They harm ozone layer more than CFC","They are used in air conditioners"],"a":3,"x":"Hydrofluorocarbons (HFCs), which replaced CFCs, are used in air conditioners and refrigerators. They have no chlorine and do not harm the ozone layer, but they are powerful greenhouse gases.","e":"The Kigali Amendment (2016) phases down HFCs.","src":["Junior Clerk 13 Nov 2021 S3"]}]}]});
